        {
            ticksSinceWarmthRegen = 0;
            millisecondsSinceWarmthRegen = 0;
            isWearingHPCape = hasHPCape;
        }
        if ( hasRegenBracelet != isWearingRegenBracelet )
        {
            ticksSinceWarmthRegen = 0;
            millisecondsSinceWarmthRegen = 0;
            isWearingRegenBracelet = hasRegenBracelet;
        }
    }

